<?php declare(strict_types=1);

// Minimal Composer-style autoloader for the acme/hello fixture: classmap plus
// PSR-4 plus files, the three maps `moggi bind` and the PHP verifier read. A
// real tree's `vendor/autoload.php` is generated by Composer; this one is
// hand-written so the fixture carries no tooling dependency. Everything it
// serves lives under this directory, because only `vendor/` travels with the
// artifact (`bundleComposerVendor` copies the tree's `vendor/`, not its root).

$base = __DIR__;
$classMap = ['Acme\\Hello\\Greeter' => $base . '/acme/hello/src/Greeter.php'];
$psr4 = ['Acme\\Hello\\' => [$base . '/acme/hello/src']];

spl_autoload_register(static function (string $class) use ($classMap, $psr4): void {
    if (isset($classMap[$class])) {
        require $classMap[$class];

        return;
    }
    foreach ($psr4 as $prefix => $dirs) {
        if ($prefix !== '' && str_starts_with($class, $prefix)) {
            foreach ((array) $dirs as $dir) {
                $file = rtrim($dir, '/') . '/' . str_replace('\\', '/', substr($class, strlen($prefix))) . '.php';
                if (is_file($file)) {
                    require $file;

                    return;
                }
            }
        }
    }
});

require_once $base . '/acme/hello/src/functions.php';
